using Xunit;
using Microsoft.Data.Sqlite;
using SmartLedger.Infrastructure.Data;
using SmartLedger.Core.Models;
using SmartLedger.Core.Services;
namespace SmartLedger.Tests;
public sealed class DatabaseIntegrationTests
{
 [Fact]public async Task Database_BootstrapsAtSchema10(){var root=Path.Combine(Path.GetTempPath(),"SL_"+Guid.NewGuid().ToString("N"));try{var db=new Database(root);await db.InitializeAsync();await using(var c=db.Open()){await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="PRAGMA user_version;";Assert.Equal(10L,Convert.ToInt64(await q.ExecuteScalarAsync()));q.CommandText="PRAGMA foreign_keys;";Assert.Equal(1L,Convert.ToInt64(await q.ExecuteScalarAsync()));}}finally{SqliteConnection.ClearAllPools();if(Directory.Exists(root))Directory.Delete(root,true);}}
 [Fact]public async Task Repository_PersistsOperationAndMaintainsTransaction(){var root=Path.Combine(Path.GetTempPath(),"SL_"+Guid.NewGuid().ToString("N"));try{var db=new Database(root);await db.InitializeAsync();var users=new UserRepository(db);var hasher=new PasswordHasher();await users.CreateAdministratorAsync(new AdminSetup("admin",hasher.Hash("Password!123"),hasher.Hash("recovery"),"hint"));var admin=await users.FindAsync("admin");Assert.NotNull(admin);var repo=new AppRepository(db);var book=(await repo.GetBooksAsync()).First(x=>x.Kind==BookKind.Customers);var person=await repo.CreatePersonAsync(book.Id,"عميل اختبار","777","اختبار");await repo.CreateOperationAsync(new LedgerOperation(Guid.NewGuid(),person.Id,OperationType.DebtToUs,125.50m,"بيع آجل",DateTimeOffset.UtcNow,admin!.Id));var loaded=await repo.GetOperationsAsync(person.Id);Assert.Single(loaded);Assert.Equal(125.50m,loaded[0].Amount);}finally{SqliteConnection.ClearAllPools();if(Directory.Exists(root))Directory.Delete(root,true);}}
 [Fact]public async Task Recycle_DeleteOperationArchivesAndRestores(){var root=Path.Combine(Path.GetTempPath(),"SL_"+Guid.NewGuid().ToString("N"));try{var db=new Database(root);await db.InitializeAsync();var users=new UserRepository(db);var h=new PasswordHasher();await users.CreateAdministratorAsync(new AdminSetup("admin",h.Hash("Password!123"),h.Hash("recovery"),"hint"));var admin=await users.FindAsync("admin");var repo=new AppRepository(db);var book=(await repo.GetBooksAsync()).First(x=>x.Kind==BookKind.Customers);var person=await repo.CreatePersonAsync(book.Id,"حساب سلة","777","");var op=await repo.CreateOperationAsync(new LedgerOperation(Guid.NewGuid(),person.Id,OperationType.DebtToUs,55m,"اختبار السلة",DateTimeOffset.UtcNow,admin!.Id));await repo.DeleteOperationAsync(op.Id,admin.Id);Assert.Empty(await repo.GetOperationsAsync(person.Id));var item=(await repo.GetDeletedItemsAsync()).Single(x=>x.EntityType=="Operation"&&x.EntityId==op.Id);await repo.RestoreDeletedItemAsync(item.Id);Assert.Equal(55m,(await repo.GetOperationsAsync(person.Id)).Single().Amount);Assert.DoesNotContain(await repo.GetDeletedItemsAsync(),x=>x.Id==item.Id);}finally{SqliteConnection.ClearAllPools();if(Directory.Exists(root))Directory.Delete(root,true);}}
 [Fact]public async Task StockMovement_RollsBackWhenStockWouldGoNegative(){var root=Path.Combine(Path.GetTempPath(),"SL_"+Guid.NewGuid().ToString("N"));try{var db=new Database(root);await db.InitializeAsync();var users=new UserRepository(db);var hasher=new PasswordHasher();await users.CreateAdministratorAsync(new AdminSetup("admin",hasher.Hash("Password!123"),hasher.Hash("recovery"),"hint"));var admin=await users.FindAsync("admin");var repo=new AppRepository(db);var p=await repo.CreateProductAsync(new Product(Guid.NewGuid(),"اختبار","","عام","كرتون","حبة",10,5,7,2,1,DateTimeOffset.UtcNow));await Assert.ThrowsAsync<InvalidOperationException>(()=>repo.CreateStockMovementAsync(new StockMovement(Guid.NewGuid(),p.Id,StockMovementType.Sale,3,7,"",DateTimeOffset.UtcNow,admin!.Id)));var loaded=(await repo.GetProductsAsync()).Single(x=>x.Id==p.Id);Assert.Equal(2m,loaded.StockSmallUnits);}finally{SqliteConnection.ClearAllPools();if(Directory.Exists(root))Directory.Delete(root,true);}}
 [Fact]public async Task AtomicInvoiceTransaction_RollsBackInvoiceLinesStockAndLedger(){var root=Path.Combine(Path.GetTempPath(),"SL_"+Guid.NewGuid().ToString("N"));try{var db=new Database(root);await db.InitializeAsync();var users=new UserRepository(db);var hasher=new PasswordHasher();await users.CreateAdministratorAsync(new AdminSetup("admin",hasher.Hash("Password!123"),hasher.Hash("recovery"),"hint"));var admin=await users.FindAsync("admin");var repo=new AppRepository(db);var book=(await repo.GetBooksAsync()).First(x=>x.Kind==BookKind.Customers);var person=await repo.CreatePersonAsync(book.Id,"عميل ذري","777","اختبار");var product=await repo.CreateProductAsync(new Product(Guid.NewGuid(),"صنف ذري","","عام","كرتون","حبة",10,5,7,2,1,DateTimeOffset.UtcNow));var invoice=new Invoice(Guid.NewGuid(),InvoiceType.Sale,person.Id,DateTimeOffset.UtcNow,21,0,21,0,PaymentMode.Credit,"اختبار ذرية",admin!.Id);var line=new InvoiceLine(Guid.NewGuid(),invoice.Id,product.Id,product.Name,3,product.SmallUnit,7,0,21);var movement=new StockMovement(Guid.NewGuid(),product.Id,StockMovementType.Sale,3,7,"اختبار ذرية",DateTimeOffset.UtcNow,admin.Id);var op=new LedgerOperation(Guid.NewGuid(),person.Id,OperationType.DebtToUs,21,"اختبار ذرية",DateTimeOffset.UtcNow,admin.Id);await Assert.ThrowsAsync<InvalidOperationException>(()=>repo.CreateInvoiceTransactionAsync(invoice,new[]{line},movement,op));var loaded=(await repo.GetProductsAsync()).Single(x=>x.Id==product.Id);Assert.Equal(2m,loaded.StockSmallUnits);await using var c=db.Open();await c.OpenAsync();foreach(var table in new[]{"Invoices","InvoiceLines","StockMovements","Operations"}){await using var q=c.CreateCommand();q.CommandText=$"SELECT COUNT(*) FROM {table};";Assert.Equal(0L,Convert.ToInt64(await q.ExecuteScalarAsync()));}}finally{SqliteConnection.ClearAllPools();if(Directory.Exists(root))Directory.Delete(root,true);}}
}

public sealed class DatabaseHardeningTests
{
 [Fact] public async Task AtomicInvoiceTransaction_CommitsInvoiceLinesStockAndLedger(){var root=Path.Combine(Path.GetTempPath(),"SL_"+Guid.NewGuid().ToString("N"));try{var db=new Database(root);await db.InitializeAsync();var users=new UserRepository(db);var hasher=new PasswordHasher();await users.CreateAdministratorAsync(new AdminSetup("admin",hasher.Hash("Password!123"),hasher.Hash("recovery"),"hint"));var admin=await users.FindAsync("admin");var repo=new AppRepository(db);var book=(await repo.GetBooksAsync()).First(x=>x.Kind==BookKind.Customers);var person=await repo.CreatePersonAsync(book.Id,"عميل نجاح","777","");var product=await repo.CreateProductAsync(new Product(Guid.NewGuid(),"صنف نجاح","","عام","كرتون","حبة",10,5,7,50,1,DateTimeOffset.UtcNow));var invoice=new Invoice(Guid.NewGuid(),InvoiceType.Sale,person.Id,DateTimeOffset.UtcNow,14,0,14,0,PaymentMode.Credit,"",admin!.Id);var line=new InvoiceLine(Guid.NewGuid(),invoice.Id,product.Id,product.Name,2,product.SmallUnit,7,0,14);var movement=new StockMovement(Guid.NewGuid(),product.Id,StockMovementType.Sale,2,7,"",DateTimeOffset.UtcNow,admin.Id);var op=new LedgerOperation(Guid.NewGuid(),person.Id,OperationType.DebtToUs,14,"",DateTimeOffset.UtcNow,admin.Id);await repo.CreateInvoiceTransactionAsync(invoice,new[]{line},movement,op);Assert.Equal(48m,(await repo.GetProductsAsync()).Single(x=>x.Id==product.Id).StockSmallUnits);Assert.Single(await repo.GetOperationsAsync(person.Id));await using var c=db.Open();await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="SELECT COUNT(*) FROM Invoices;";Assert.Equal(1L,Convert.ToInt64(await q.ExecuteScalarAsync()));q.CommandText="SELECT COUNT(*) FROM InvoiceLines;";Assert.Equal(1L,Convert.ToInt64(await q.ExecuteScalarAsync()));q.CommandText="PRAGMA foreign_key_check;";await using var r=await q.ExecuteReaderAsync();Assert.False(await r.ReadAsync());}finally{SqliteConnection.ClearAllPools();if(Directory.Exists(root))Directory.Delete(root,true);}}
 [Fact] public async Task LegacyOccrredAt_IsRepairedToOccurredAt(){var root=Path.Combine(Path.GetTempPath(),"SL_"+Guid.NewGuid().ToString("N"));try{await using(var c=new SqliteConnection("Data Source="+Path.Combine(root,"smartledger.db"))){Directory.CreateDirectory(root);await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="CREATE TABLE Users(Id TEXT PRIMARY KEY,UserName TEXT NOT NULL UNIQUE,DisplayName TEXT NOT NULL,PasswordHash TEXT NOT NULL,RecoveryHash TEXT NOT NULL DEFAULT '',RecoveryHint TEXT NOT NULL DEFAULT '',IsAdministrator INTEGER NOT NULL,IsActive INTEGER NOT NULL,CreatedAt TEXT NOT NULL);CREATE TABLE Books(Id TEXT PRIMARY KEY,Name TEXT NOT NULL,Kind INTEGER NOT NULL,SortOrder INTEGER NOT NULL,IsSystem INTEGER NOT NULL,Color TEXT NOT NULL,Icon TEXT NOT NULL);CREATE TABLE BusinessIdentity(Id INTEGER PRIMARY KEY CHECK(Id=1),BusinessName TEXT NOT NULL,LogoPath TEXT NOT NULL DEFAULT '',Phone TEXT NOT NULL DEFAULT '',Address TEXT NOT NULL DEFAULT '',Currency TEXT NOT NULL DEFAULT 'ريال');CREATE TABLE Operations(Id TEXT PRIMARY KEY,PersonId TEXT NOT NULL,Type INTEGER NOT NULL,Amount TEXT NOT NULL,Note TEXT NOT NULL DEFAULT '',OccrredAt TEXT NOT NULL,CreatedBy TEXT NOT NULL);CREATE TABLE StockMovements(Id TEXT PRIMARY KEY,ProductId TEXT NOT NULL,Type INTEGER NOT NULL,QuantitySmallUnits TEXT NOT NULL,UnitPrice TEXT NOT NULL,Note TEXT NOT NULL DEFAULT '',OccrredAt TEXT NOT NULL,CreatedBy TEXT NOT NULL);CREATE TABLE Expenses(Id TEXT PRIMARY KEY,PersonId TEXT NULL,Category TEXT NOT NULL,Amount TEXT NOT NULL,Note TEXT NOT NULL DEFAULT '',OccrredAt TEXT NOT NULL,CreatedBy TEXT NOT NULL);CREATE TABLE AuditLogs(Id TEXT PRIMARY KEY,UserId TEXT NULL,Action TEXT NOT NULL,EntityType TEXT NOT NULL,EntityId TEXT NULL,Details TEXT NOT NULL,OccrredAt TEXT NOT NULL);INSERT INTO Books VALUES('1','كل الحسابات',0,0,1,'','');INSERT INTO BusinessIdentity VALUES(1,'الدفتر الذكي','','','','ريال');PRAGMA user_version=3;";await q.ExecuteNonQueryAsync();}var db=new Database(root);await db.InitializeAsync();await using(var c=db.Open()){await c.OpenAsync();foreach(var table in new[]{"Operations","StockMovements","Expenses","AuditLogs"}){await using var q=c.CreateCommand();q.CommandText=$"PRAGMA table_info({table});";await using var r=await q.ExecuteReaderAsync();var names=new List<string>();while(await r.ReadAsync())names.Add(r.GetString(1));Assert.Contains("OccurredAt",names);Assert.DoesNotContain("OccrredAt",names);}await using var v=c.CreateCommand();v.CommandText="PRAGMA user_version;";Assert.Equal(10L,Convert.ToInt64(await v.ExecuteScalarAsync()));}}finally{SqliteConnection.ClearAllPools();if(Directory.Exists(root))Directory.Delete(root,true);}}
}

public sealed class FeatureHardeningTests
{
 [Fact] public async Task MessageTemplates_PersistAndUpdate(){var root=Path.Combine(Path.GetTempPath(),"SL_"+Guid.NewGuid().ToString("N"));try{var db=new Database(root);await db.InitializeAsync();var repo=new AppRepository(db);var t=new MessageTemplate(Guid.NewGuid(),"اختبار قالب","السلام عليكم {الاسم}",false);await repo.SaveMessageTemplateAsync(t);Assert.Equal(t.Body,(await repo.GetMessageTemplatesAsync()).Single(x=>x.Id==t.Id).Body);var changed=t with {Body="تم التحديث {المبلغ}"};await repo.SaveMessageTemplateAsync(changed);Assert.Equal("تم التحديث {المبلغ}",(await repo.GetMessageTemplatesAsync()).Single(x=>x.Id==t.Id).Body);}finally{SqliteConnection.ClearAllPools();if(Directory.Exists(root))Directory.Delete(root,true);}}
 [Fact] public async Task RecycleBin_RestoresBookPayload(){var root=Path.Combine(Path.GetTempPath(),"SL_"+Guid.NewGuid().ToString("N"));try{var db=new Database(root);await db.InitializeAsync();var repo=new AppRepository(db);var id=Guid.NewGuid();var payload=$$"""{"Id":"{{id:N}}","Name":"دفتر مؤقت","Kind":3,"SortOrder":99,"IsSystem":false,"Color":"#123456","Icon":"book"}""";await using(var c=db.Open()){await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="INSERT INTO DeletedItems VALUES($id,'Book',$entity,$when,$user,$payload);";q.Parameters.AddWithValue("$id",Guid.NewGuid().ToString("N"));q.Parameters.AddWithValue("$entity",id.ToString("N"));q.Parameters.AddWithValue("$when",DateTimeOffset.UtcNow.ToString("O"));q.Parameters.AddWithValue("$user",Guid.NewGuid().ToString("N"));q.Parameters.AddWithValue("$payload",payload);await q.ExecuteNonQueryAsync();}var item=(await repo.GetDeletedItemsAsync()).Single(x=>x.EntityId==id);await repo.RestoreDeletedItemAsync(item.Id);Assert.Contains((await repo.GetBooksAsync()),x=>x.Id==id&&x.Name=="دفتر مؤقت");Assert.DoesNotContain(await repo.GetDeletedItemsAsync(),x=>x.Id==item.Id);}finally{SqliteConnection.ClearAllPools();if(Directory.Exists(root))Directory.Delete(root,true);}}
}

public sealed class PreDeliveryHardeningTests
{
 [Fact] public async Task InvoiceValidation_RejectsNegativePriceWithoutCreatingOrphans(){var root=Path.Combine(Path.GetTempPath(),"SL_"+Guid.NewGuid().ToString("N"));try{var db=new Database(root);await db.InitializeAsync();var users=new UserRepository(db);var h=new PasswordHasher();await users.CreateAdministratorAsync(new AdminSetup("admin",h.Hash("Password!123"),h.Hash("recovery"),"hint"));var admin=await users.FindAsync("admin");var repo=new AppRepository(db);var book=(await repo.GetBooksAsync()).First(x=>x.Kind==BookKind.Customers);var person=await repo.CreatePersonAsync(book.Id,"عميل تحقق","1","");var product=await repo.CreateProductAsync(new Product(Guid.NewGuid(),"صنف تحقق","","عام","كرتون","حبة",10,5,7,20,1,DateTimeOffset.UtcNow));var invoice=new Invoice(Guid.NewGuid(),InvoiceType.Sale,person.Id,DateTimeOffset.UtcNow,-7,0,-7,0,PaymentMode.Credit,"",admin!.Id);var line=new InvoiceLine(Guid.NewGuid(),invoice.Id,product.Id,product.Name,1,product.SmallUnit,-7,0,-7);var movement=new StockMovement(Guid.NewGuid(),product.Id,StockMovementType.Sale,10,-7,"",DateTimeOffset.UtcNow,admin.Id);var op=new LedgerOperation(Guid.NewGuid(),person.Id,OperationType.DebtToUs,7,"",DateTimeOffset.UtcNow,admin.Id);await Assert.ThrowsAsync<ArgumentOutOfRangeException>(()=>repo.CreateInvoiceTransactionAsync(invoice,new[]{line},movement,op));await using var c=db.Open();await c.OpenAsync();foreach(var table in new[]{"Invoices","InvoiceLines","StockMovements","Operations"}){await using var q=c.CreateCommand();q.CommandText=$"SELECT COUNT(*) FROM {table};";Assert.Equal(0L,Convert.ToInt64(await q.ExecuteScalarAsync()));}}finally{SqliteConnection.ClearAllPools();if(Directory.Exists(root))Directory.Delete(root,true);}}
 [Fact] public async Task DuplicateInvoice_IsRejectedWithoutSecondStockOrLedgerEffect(){var root=Path.Combine(Path.GetTempPath(),"SL_"+Guid.NewGuid().ToString("N"));try{var db=new Database(root);await db.InitializeAsync();var users=new UserRepository(db);var h=new PasswordHasher();await users.CreateAdministratorAsync(new AdminSetup("admin",h.Hash("Password!123"),h.Hash("recovery"),"hint"));var admin=await users.FindAsync("admin");var repo=new AppRepository(db);var book=(await repo.GetBooksAsync()).First(x=>x.Kind==BookKind.Customers);var person=await repo.CreatePersonAsync(book.Id,"عميل تكرار","2","");var product=await repo.CreateProductAsync(new Product(Guid.NewGuid(),"صنف تكرار","","عام","كرتون","حبة",1,5,10,20,1,DateTimeOffset.UtcNow));var id=Guid.NewGuid();var invoice=new Invoice(id,InvoiceType.Sale,person.Id,DateTimeOffset.UtcNow,10,0,10,0,PaymentMode.Credit,"",admin!.Id);var line=new InvoiceLine(Guid.NewGuid(),id,product.Id,product.Name,1,product.SmallUnit,10,0,10);var movement=new StockMovement(Guid.NewGuid(),product.Id,StockMovementType.Sale,1,10,"",DateTimeOffset.UtcNow,admin.Id);var op=new LedgerOperation(Guid.NewGuid(),person.Id,OperationType.DebtToUs,10,"",DateTimeOffset.UtcNow,admin.Id);await repo.CreateInvoiceTransactionAsync(invoice,new[]{line},movement,op);var duplicateLine=new InvoiceLine(Guid.NewGuid(),id,product.Id,product.Name,1,product.SmallUnit,10,0,10);var duplicateMovement=new StockMovement(Guid.NewGuid(),product.Id,StockMovementType.Sale,1,10,"",DateTimeOffset.UtcNow,admin.Id);var duplicateOp=new LedgerOperation(Guid.NewGuid(),person.Id,OperationType.DebtToUs,10,"",DateTimeOffset.UtcNow,admin.Id);await Assert.ThrowsAsync<InvalidOperationException>(()=>repo.CreateInvoiceTransactionAsync(invoice,new[]{duplicateLine},duplicateMovement,duplicateOp));Assert.Equal(19m,(await repo.GetProductsAsync()).Single(x=>x.Id==product.Id).StockSmallUnits);Assert.Single(await repo.GetOperationsAsync(person.Id));}finally{SqliteConnection.ClearAllPools();if(Directory.Exists(root))Directory.Delete(root,true);}}
 [Fact] public async Task BackupRestore_ValidatesHashAndRollsBackOnInvalidArchive(){var root=Path.Combine(Path.GetTempPath(),"SL_"+Guid.NewGuid().ToString("N"));var backupDir=Path.Combine(root,"backups");try{var db=new Database(root);await db.InitializeAsync();var repo=new AppRepository(db);await repo.SaveIdentityAsync(new BusinessIdentity("قبل النسخ","","","اختبار","ريال"));var service=new SmartLedger.Infrastructure.Backup.BackupService(root);var backup=await service.CreateAsync(backupDir);await repo.SaveIdentityAsync(new BusinessIdentity("بعد النسخ","","","اختبار","ريال"));await service.RestoreAsync(backup.FilePath);Assert.Equal("قبل النسخ",(await repo.GetIdentityAsync()).BusinessName);var bad=Path.Combine(backupDir,"bad.zip");await File.WriteAllTextAsync(bad,"ليس أرشيفاً");await Assert.ThrowsAnyAsync<Exception>(()=>service.RestoreAsync(bad));Assert.Equal("قبل النسخ",(await repo.GetIdentityAsync()).BusinessName);}finally{SqliteConnection.ClearAllPools();if(Directory.Exists(root))Directory.Delete(root,true);}}
 [Fact] public async Task ProductCreation_RejectsDuplicateNormalizedNameAndBarcode(){var root=Path.Combine(Path.GetTempPath(),"SL_"+Guid.NewGuid().ToString("N"));try{var db=new Database(root);await db.InitializeAsync();var repo=new AppRepository(db);var first=await repo.CreateProductAsync(new Product(Guid.NewGuid(),"أدوية","ABC-123","عام","كرتون","حبة",12,5,9,0,1,DateTimeOffset.UtcNow));await Assert.ThrowsAsync<InvalidOperationException>(()=>repo.CreateProductAsync(new Product(Guid.NewGuid(),"ادويه","XYZ-999","عام","كرتون","حبة",12,5,9,0,1,DateTimeOffset.UtcNow)));await Assert.ThrowsAsync<InvalidOperationException>(()=>repo.CreateProductAsync(new Product(Guid.NewGuid(),"صنف مختلف","ABC-123","عام","كرتون","حبة",12,5,9,0,1,DateTimeOffset.UtcNow)));var products=await repo.GetProductsAsync();Assert.Single(products);Assert.Equal(first.Id,products[0].Id);}finally{SqliteConnection.ClearAllPools();if(Directory.Exists(root))Directory.Delete(root,true);}}
 [Fact] public async Task MultiLineInvoice_CommitsEveryLineAndMovementAtomically(){var root=Path.Combine(Path.GetTempPath(),"SL_"+Guid.NewGuid().ToString("N"));try{var db=new Database(root);await db.InitializeAsync();var users=new UserRepository(db);var h=new PasswordHasher();await users.CreateAdministratorAsync(new AdminSetup("admin",h.Hash("Password!123"),h.Hash("recovery"),"hint"));var admin=await users.FindAsync("admin");var repo=new AppRepository(db);var product=await repo.CreateProductAsync(new Product(Guid.NewGuid(),"صنف متعدد البنود","","عام","كرتون","حبة",12,5,10,50,1,DateTimeOffset.UtcNow));var invoiceId=Guid.NewGuid();var invoice=new Invoice(invoiceId,InvoiceType.Sale,null,DateTimeOffset.UtcNow,236,0,236,236,PaymentMode.Cash,"اختبار متعدد البنود",admin!.Id);var lines=new[]{new InvoiceLine(Guid.NewGuid(),invoiceId,product.Id,product.Name,2,"كرتون",100,0,200),new InvoiceLine(Guid.NewGuid(),invoiceId,product.Id,product.Name,3,"حبة",12,0,36)};var movements=new[]{new StockMovement(Guid.NewGuid(),product.Id,StockMovementType.Sale,24,8.3333m,"",DateTimeOffset.UtcNow,admin.Id),new StockMovement(Guid.NewGuid(),product.Id,StockMovementType.Sale,3,12,"",DateTimeOffset.UtcNow,admin.Id)};await repo.CreateInvoiceTransactionWithMovementsAsync(invoice,lines,movements,null);Assert.Equal(23m,(await repo.GetProductsAsync()).Single(x=>x.Id==product.Id).StockSmallUnits);await using var c=db.Open();await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="SELECT COUNT(*) FROM InvoiceLines WHERE InvoiceId=$id;";q.Parameters.AddWithValue("$id",invoiceId.ToString("N"));Assert.Equal(2L,Convert.ToInt64(await q.ExecuteScalarAsync()));q.Parameters.Clear();q.CommandText="SELECT COUNT(*) FROM StockMovements WHERE InvoiceId=$id;";q.Parameters.AddWithValue("$id",invoiceId.ToString("N"));Assert.Equal(2L,Convert.ToInt64(await q.ExecuteScalarAsync()));}finally{SqliteConnection.ClearAllPools();if(Directory.Exists(root))Directory.Delete(root,true);}}
