public sealed class FinancialPathTests
{
 [Fact] public async Task InvoicePaymentModes_CashCreditPartialPreserveTotalsAndBalances(){var root=Path.Combine(Path.GetTempPath(),"SL_"+Guid.NewGuid().ToString("N"));try{var db=new Database(root);await db.InitializeAsync();var users=new UserRepository(db);var h=new PasswordHasher();await users.CreateAdministratorAsync(new AdminSetup("admin",h.Hash("Password!123"),h.Hash("recovery"),"hint"));var admin=await users.FindAsync("admin");var repo=new AppRepository(db);var customerBook=(await repo.GetBooksAsync()).First(x=>x.Kind==BookKind.Customers);var supplierBook=(await repo.GetBooksAsync()).First(x=>x.Kind==BookKind.Suppliers);var customer=await repo.CreatePersonAsync(customerBook.Id,"عميل مالي","10","");var supplier=await repo.CreatePersonAsync(supplierBook.Id,"مورد مالي","11","");var product=await repo.CreateProductAsync(new Product(Guid.NewGuid(),"صنف مالي","","عام","كرتون","حبة",1,5,10,20,1,DateTimeOffset.UtcNow));var cash=new Invoice(Guid.NewGuid(),InvoiceType.Sale,null,DateTimeOffset.UtcNow,10,0,10,10,PaymentMode.Cash,"",admin!.Id);await repo.CreateInvoiceTransactionAsync(cash,new[]{new InvoiceLine(Guid.NewGuid(),cash.Id,product.Id,product.Name,1,product.SmallUnit,10,0,10)},new StockMovement(Guid.NewGuid(),product.Id,StockMovementType.Sale,1,10,"",DateTimeOffset.UtcNow,admin.Id),null);var credit=new Invoice(Guid.NewGuid(),InvoiceType.Sale,customer.Id,DateTimeOffset.UtcNow,20,0,20,0,PaymentMode.Credit,"",admin.Id);await repo.CreateInvoiceTransactionAsync(credit,new[]{new InvoiceLine(Guid.NewGuid(),credit.Id,product.Id,product.Name,2,product.SmallUnit,10,0,20)},new StockMovement(Guid.NewGuid(),product.Id,StockMovementType.Sale,2,10,"",DateTimeOffset.UtcNow,admin.Id),new LedgerOperation(Guid.NewGuid(),customer.Id,OperationType.DebtToUs,20,"",DateTimeOffset.UtcNow,admin.Id));var partial=new Invoice(Guid.NewGuid(),InvoiceType.Purchase,supplier.Id,DateTimeOffset.UtcNow,10,0,10,4,PaymentMode.Partial,"",admin.Id);await repo.CreateInvoiceTransactionAsync(partial,new[]{new InvoiceLine(Guid.NewGuid(),partial.Id,product.Id,product.Name,1,product.SmallUnit,10,0,10)},new StockMovement(Guid.NewGuid(),product.Id,StockMovementType.Purchase,1,10,"",DateTimeOffset.UtcNow,admin.Id),new LedgerOperation(Guid.NewGuid(),supplier.Id,OperationType.DebtOnUs,6,"",DateTimeOffset.UtcNow,admin.Id));Assert.Equal(18m,(await repo.GetProductsAsync()).Single(x=>x.Id==product.Id).StockSmallUnits);Assert.Equal(20m,(await repo.GetOperationsAsync(customer.Id)).Single().Amount);Assert.Equal(6m,(await repo.GetOperationsAsync(supplier.Id)).Single().Amount);await using var c=db.Open();await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="SELECT COUNT(*) FROM Invoices;";Assert.Equal(3L,Convert.ToInt64(await q.ExecuteScalarAsync()));}finally{SqliteConnection.ClearAllPools();if(Directory.Exists(root))Directory.Delete(root,true);}}
 [Fact] public async Task OperationAndProductValidation_RejectsNegativeAmountsAndInvalidProductValues(){var root=Path.Combine(Path.GetTempPath(),"SL_"+Guid.NewGuid().ToString("N"));try{var db=new Database(root);await db.InitializeAsync();var users=new UserRepository(db);var h=new PasswordHasher();await users.CreateAdministratorAsync(new AdminSetup("admin",h.Hash("Password!123"),h.Hash("recovery"),"hint"));var admin=await users.FindAsync("admin");var repo=new AppRepository(db);var book=(await repo.GetBooksAsync()).First(x=>x.Kind==BookKind.Customers);var person=await repo.CreatePersonAsync(book.Id,"حساب تحقق","12","");await Assert.ThrowsAsync<ArgumentOutOfRangeException>(()=>repo.CreateOperationAsync(new LedgerOperation(Guid.NewGuid(),person.Id,OperationType.Receive,-1,"",DateTimeOffset.UtcNow,admin!.Id)));await Assert.ThrowsAsync<ArgumentOutOfRangeException>(()=>repo.CreateProductAsync(new Product(Guid.NewGuid(),"صنف غير صالح","","عام","كرتون","حبة",0,5,10,1,1,DateTimeOffset.UtcNow)));}finally{SqliteConnection.ClearAllPools();if(Directory.Exists(root))Directory.Delete(root,true);}}
}


public sealed class RecycleStockHardeningTests
{
 [Fact] public async Task RestoringStockMovement_RestoresMovementAndReappliesStockEffect()
 {
  var root=Path.Combine(Path.GetTempPath(),"SL_"+Guid.NewGuid().ToString("N"));
  try
  {
   var db=new Database(root); await db.InitializeAsync();
   var users=new UserRepository(db); var h=new PasswordHasher();
   await users.CreateAdministratorAsync(new AdminSetup("admin",h.Hash("Password!123"),h.Hash("recovery"),"hint"));
   var admin=await users.FindAsync("admin"); Assert.NotNull(admin);
   var repo=new AppRepository(db);
   var product=await repo.CreateProductAsync(new Product(Guid.NewGuid(),"صنف استعادة","","عام","كرتون","حبة",1,5,10,10,1,DateTimeOffset.UtcNow));
   var movement=await repo.CreateStockMovementAsync(new StockMovement(Guid.NewGuid(),product.Id,StockMovementType.Sale,3,10,"اختبار استعادة",DateTimeOffset.UtcNow,admin!.Id));
   Assert.Equal(7m,(await repo.GetProductsAsync()).Single(x=>x.Id==product.Id).StockSmallUnits);
   await repo.DeleteStockMovementAsync(movement.Id,admin.Id);
   Assert.Equal(10m,(await repo.GetProductsAsync()).Single(x=>x.Id==product.Id).StockSmallUnits);
   var item=(await repo.GetDeletedItemsAsync()).Single(x=>x.EntityType=="StockMovement"&&x.EntityId==movement.Id);
   await repo.RestoreDeletedItemAsync(item.Id);
   Assert.Equal(7m,(await repo.GetProductsAsync()).Single(x=>x.Id==product.Id).StockSmallUnits);
   Assert.DoesNotContain(await repo.GetDeletedItemsAsync(),x=>x.EntityId==movement.Id);
  }
  finally { SqliteConnection.ClearAllPools(); if(Directory.Exists(root)) Directory.Delete(root,true); }
 }
}
